    OrganizationalUnitScope.add_member(:organizational_units, Smithy::Schema::Shapes::ShapeRef.new(shape: OrganizationalUnitIdList, location_name: 'OrganizationalUnits', traits: {"smithy.api#documentation" => "<p>The list of OUs within the organization that the specified Firewall Manager administrator either can or cannot apply policies to, based on the value of <code>OrganizationalUnitScope$ExcludeSpecifiedOrganizationalUnits</code>. If <code>OrganizationalUnitScope$ExcludeSpecifiedOrganizationalUnits</code> is set to <code>true</code>, then the Firewall Manager administrator can apply policies to all OUs in the organization except for the OUs in this list. If <code>OrganizationalUnitScope$ExcludeSpecifiedOrganizationalUnits</code> is set to <code>false</code>, then the Firewall Manager administrator can only apply policies to the OUs in this list.</p>"}))
    OrganizationalUnitScope.add_member(:all_organizational_units_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllOrganizationalUnitsEnabled', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A boolean value that indicates if the administrator can apply policies to all OUs within an organization. If true, the administrator can manage all OUs within the organization. You can either enable management of all OUs through this operation, or you can specify OUs to manage in <code>OrganizationalUnitScope$OrganizationalUnits</code>. You cannot specify both.</p>"}))
    OrganizationalUnitScope.add_member(:exclude_specified_organizational_units, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ExcludeSpecifiedOrganizationalUnits', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A boolean value that excludes the OUs in <code>OrganizationalUnitScope$OrganizationalUnits</code> from the administrator's scope. If true, the Firewall Manager administrator can apply policies to all OUs in the organization except for the OUs listed in <code>OrganizationalUnitScope$OrganizationalUnits</code>. You can either specify a list of OUs to exclude by <code>OrganizationalUnitScope$OrganizationalUnits</code>, or you can enable management of all OUs by <code>OrganizationalUnitScope$AllOrganizationalUnitsEnabled</code>. You cannot specify both.</p>"}))
