    Policy.add_member(:policy_update_token, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyUpdateToken, location_name: 'PolicyUpdateToken', traits: {"smithy.api#documentation" => "<p>A unique identifier for each update to the policy. When issuing a <code>PutPolicy</code>\n      request, the <code>PolicyUpdateToken</code> in the request must match the\n        <code>PolicyUpdateToken</code> of the current policy version. To get the\n        <code>PolicyUpdateToken</code> of the current policy version, use a <code>GetPolicy</code>\n      request.</p>"}))
    Policy.add_member(:security_service_policy_data, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityServicePolicyData, location_name: 'SecurityServicePolicyData', traits: {"smithy.api#documentation" => "<p>Details about the security service that is being used to protect the resources.</p>", "smithy.api#required" => {}}))
    Policy.add_member(:resource_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceType, location_name: 'ResourceType', traits: {"smithy.api#documentation" => "<p>The type of resource protected by or in scope of the policy. This is in the format shown\n        in the <a href=\"https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/aws-template-resource-type-ref.html\">Amazon Web Services Resource Types Reference</a>.\n                    To apply this policy to multiple resource types, specify a resource type of <code>ResourceTypeList</code> and then specify the resource types in a <code>ResourceTypeList</code>.</p>\n         <p>The following are valid resource types for each Firewall Manager policy type:</p>\n         <ul>\n            <li>\n               <p>Amazon Web Services WAF Classic - <code>AWS::ApiGateway::Stage</code>, <code>AWS::CloudFront::Distribution</code>, and <code>AWS::ElasticLoadBalancingV2::LoadBalancer</code>.</p>\n            </li>\n            <li>\n               <p>WAF - <code>AWS::ApiGateway::Stage</code>, <code>AWS::ElasticLoadBalancingV2::LoadBalancer</code>, and <code>AWS::CloudFront::Distribution</code>.</p>\n            </li>\n            <li>\n               <p>Shield Advanced - <code>AWS::ElasticLoadBalancingV2::LoadBalancer</code>, <code>AWS::ElasticLoadBalancing::LoadBalancer</code>, <code>AWS::EC2::EIP</code>, and <code>AWS::CloudFront::Distribution</code>.</p>\n            </li>\n            <li>\n               <p>Network ACL - <code>AWS::EC2::Subnet</code>.</p>\n            </li>\n            <li>\n               <p>Security group usage audit - <code>AWS::EC2::SecurityGroup</code>.</p>\n            </li>\n            <li>\n               <p>Security group content audit - <code>AWS::EC2::SecurityGroup</code>, <code>AWS::EC2::NetworkInterface</code>, and <code>AWS::EC2::Instance</code>.</p>\n            </li>\n            <li>\n               <p>DNS Firewall, Network Firewall, and third-party firewall - <code>AWS::EC2::VPC</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    Policy.add_member(:resource_type_list, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceTypeList, location_name: 'ResourceTypeList', traits: {"smithy.api#documentation" => "<p>An array of <code>ResourceType</code> objects. Use this only to specify multiple resource types. To specify a single resource type, use <code>ResourceType</code>.</p>"}))
    Policy.add_member(:resource_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceTags, location_name: 'ResourceTags', traits: {"smithy.api#documentation" => "<p>An array of <code>ResourceTag</code> objects.</p>"}))
    Policy.add_member(:exclude_resource_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ExcludeResourceTags', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>If set to <code>True</code>, resources with the tags that are specified in the\n        <code>ResourceTag</code> array are not in scope of the policy. If set to <code>False</code>,\n      and the <code>ResourceTag</code> array is not null, only resources with the specified tags are\n      in scope of the policy.</p>", "smithy.api#required" => {}}))
    Policy.add_member(:remediation_enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'RemediationEnabled', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates if the policy should be automatically applied to new resources.</p>", "smithy.api#required" => {}}))
    Policy.add_member(:delete_unused_fm_managed_resources, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DeleteUnusedFMManagedResources', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether Firewall Manager should automatically remove protections from resources that leave the policy scope and clean up resources\n   that Firewall Manager is managing for accounts when those accounts leave policy scope. For example, Firewall Manager will disassociate a Firewall Manager managed web ACL\n   from a protected customer resource when the customer resource leaves policy scope. </p>\n         <p>By default, Firewall Manager doesn't remove protections or delete Firewall Manager managed resources. </p>\n         <p>This option is not available for Shield Advanced or WAF Classic policies.</p>"}))
    Policy.add_member(:include_map, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomerPolicyScopeMap, location_name: 'IncludeMap', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Web Services account IDs and Organizations organizational units (OUs) to include in the policy.\n          Specifying an OU is the equivalent of specifying all accounts in the OU and in any of its child OUs, including any child OUs and accounts that are added at a later time.</p>\n         <p>You can specify inclusions or exclusions, but not both. If you specify an <code>IncludeMap</code>, Firewall Manager\n          applies the policy to all accounts specified by the <code>IncludeMap</code>, and\n          does not evaluate any <code>ExcludeMap</code> specifications. If you do not specify an <code>IncludeMap</code>, then Firewall Manager\n            applies the policy to all accounts except for those specified by the <code>ExcludeMap</code>.</p>\n         <p>You can specify account IDs, OUs, or a combination: </p>\n         <ul>\n            <li>\n               <p>Specify account IDs by setting the key to <code>ACCOUNT</code>. For example, the following is a valid map:\n      <code>{“ACCOUNT” : [“accountID1”, “accountID2”]}</code>.</p>\n            </li>\n            <li>\n               <p>Specify OUs by setting the key to <code>ORG_UNIT</code>. For example, the following is a valid map:\n  <code>{“ORG_UNIT” : [“ouid111”, “ouid112”]}</code>.</p>\n            </li>\n            <li>\n               <p>Specify accounts and OUs together in a single map, separated with a comma. For example, the following is a valid map:\n      <code>{“ACCOUNT” : [“accountID1”, “accountID2”], “ORG_UNIT” : [“ouid111”, “ouid112”]}</code>.</p>\n            </li>\n         </ul>"}))
    Policy.add_member(:exclude_map, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomerPolicyScopeMap, location_name: 'ExcludeMap', traits: {"smithy.api#documentation" => "<p>Specifies the Amazon Web Services account IDs and Organizations organizational units (OUs) to exclude from the policy.\n          Specifying an OU is the equivalent of specifying all accounts in the OU and in any of its child OUs, including any child OUs and accounts that are added at a later time.</p>\n         <p>You can specify inclusions or exclusions, but not both. If you specify an <code>IncludeMap</code>, Firewall Manager\n          applies the policy to all accounts specified by the <code>IncludeMap</code>, and\n          does not evaluate any <code>ExcludeMap</code> specifications. If you do not specify an <code>IncludeMap</code>, then Firewall Manager\n            applies the policy to all accounts except for those specified by the <code>ExcludeMap</code>.</p>\n         <p>You can specify account IDs, OUs, or a combination: </p>\n         <ul>\n            <li>\n               <p>Specify account IDs by setting the key to <code>ACCOUNT</code>. For example, the following is a valid map:\n      <code>{“ACCOUNT” : [“accountID1”, “accountID2”]}</code>.</p>\n            </li>\n            <li>\n               <p>Specify OUs by setting the key to <code>ORG_UNIT</code>. For example, the following is a valid map:\n  <code>{“ORG_UNIT” : [“ouid111”, “ouid112”]}</code>.</p>\n            </li>\n            <li>\n               <p>Specify accounts and OUs together in a single map, separated with a comma. For example, the following is a valid map:\n      <code>{“ACCOUNT” : [“accountID1”, “accountID2”], “ORG_UNIT” : [“ouid111”, “ouid112”]}</code>.</p>\n            </li>\n         </ul>"}))
    Policy.add_member(:resource_set_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceSetIds, location_name: 'ResourceSetIds', traits: {"smithy.api#documentation" => "<p>The unique identifiers of the resource sets used by the policy.</p>"}))
    Policy.add_member(:policy_description, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceDescription, location_name: 'PolicyDescription', traits: {"smithy.api#documentation" => "<p>Your description of the Firewall Manager policy.</p>"}))
    Policy.add_member(:policy_status, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomerPolicyStatus, location_name: 'PolicyStatus', traits: {"smithy.api#documentation" => "<p>Indicates whether the policy is in or out of an admin's policy or Region scope.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ACTIVE</code> - The administrator can manage and delete the policy.</p>\n            </li>\n            <li>\n               <p>\n                  <code>OUT_OF_ADMIN_SCOPE</code> - The administrator can view the policy, but they can't edit or delete the policy. Existing policy protections stay in place. Any new resources that come into scope of the policy won't be protected.</p>\n            </li>\n         </ul>"}))
